	allegiance = "Ella misma · servida por el Martillo Crepuscular",
	sections = {
		{
			title = "Resumen",
			text = [=[Myzrael es un ser de la tierra profunda que yace atada bajo las {link:arathi-highlands}Tierras Altas de Arathi{/link}. Se llama a sí misma princesa de la tierra. Los gigantes la encadenaron allí, y cuatro Piedras de Vínculo la mantienen inmovilizada. Solo puede hablar al mundo de arriba a través de fragmentos de cristal, y habla con dulzura, suplicando que la rescaten.]=],
		},
		{
			title = "Importancia",
			text = [=[Myzrael es el secreto de las tierras altas. El {link:twilight-s-hammer}Martillo Crepuscular{/link} la llama la Dama y trabaja por su regreso. Quien huyó de su orden con su pergamino cree que los gigantes la ataron por una razón, y que nunca debe permitírsele cobrar fuerza.]=],
