})

Translate("esMX", "thoradin", {
	title = "Thoradin",
	subtitle = "Primer rey de Arathor",
	allegiance = "La tribu Arathi · Arathor",
	sections = {
		{
			title = "Resumen",
			text = [=[Thoradin fue el caudillo de la tribu {link:arathi-highlands}Arathi{/link} que hizo de la humanidad una nación. En una época en que las tribus humanas del norte luchaban entre sí mientras los trols las cazaban a todas, las unió bajo un solo estandarte. Llamó al nuevo reino {link:arathor}Arathor{/link} y levantó su capital, {link:stromgarde-keep}Strom{/link}, en las tierras altas que llevan el nombre de su tribu. Todos los reinos humanos de hoy descienden de su obra.]=],
		},
		{
			title = "Importancia",
			text = [=[Antes de Thoradin había tribus. Después de él hubo un pueblo. Su alianza con los elfos ganó las {link:troll-wars}Guerras Trols{/link} y trajo a la humanidad el conocimiento de la magia, y los elfos de {link:quel-thalas}Quel'Thalas{/link} honraron su linaje durante miles de años. La gran muralla entre las tierras altas y {link:hillsbrad-foothills}Trabalomas{/link} aún lleva su nombre.]=],
		},
		{
			title = "La unión de las tribus",
			text = [=[Los {link:arathi-highlands}Arathi{/link} habían luchado contra los Amani más tiempo que ninguna otra tribu, y Thoradin había aprendido la guerra en la frontera trol. Vio lo que los demás jefes no querían ver: que los trols destruirían las tribus una a una. Las unió por todos los medios a su alcance. A unas las ganó por matrimonio, a otras con promesas de tierras y riquezas, y a otras las derrotó en batalla. A los que derrotó no los humilló. Hizo de sus jefes sus generales, y así se convirtieron en sus hombres más leales.]=],
		},
		{
			title = "Strom",
			text = [=[Thoradin estableció su capital en las llanuras secas de las tierras altas, lejos de los bosques espesos donde los trols tendían sus emboscadas. La fortaleza de {link:stromgarde-keep}Strom{/link} se convirtió en un lugar de refugio, y los humanos acudieron a ella desde todo el continente. Aquí, también, la humanidad aprendió por primera vez las artes arcanas.]=],
		},
		{
			title = "Las Guerras Trols",
			text = [=[Cuando los Amani cayeron sobre {link:quel-thalas}Quel'Thalas{/link}, los elfos enviaron emisarios a {link:stromgarde-keep}Strom{/link}. Prometieron enseñar a cien humanos los caminos de la magia a cambio de las espadas de {link:arathor}Arathor{/link}. Thoradin aceptó. Su hueste golpeó a los trols en el sur de las tierras élficas y los atrajo a las estribaciones de las {link:alterac-mountains}Montañas de Alterac{/link}, donde los elfos y los nuevos magos humanos cayeron sobre ellos desde el otro lado. Los Amani quedaron quebrados. En gratitud, los elfos juraron amistad al linaje de Thoradin.]=],
		},
		{
			title = "El legado",
			text = [=[Thoradin deseaba que {link:stromgarde-keep}Strom{/link} siguiera siendo el corazón de su reino, y temía un imperio demasiado extenso. Tras él, su pueblo partió de todos modos y fundó {link:city-of-dalaran}Dalaran{/link}, {link:gilneas}Gilneas{/link}, {link:kul-tiras}Kul Tiras{/link}, {link:alterac-mountains}Alterac{/link} y Lordaeron. Strom decayó. Al final, los últimos de su linaje la abandonaron y navegaron al sur para fundar un nuevo reino. Muchos siglos después, {link:anduin-lothar}Anduin Lothar{/link}, el último de ese linaje, dirigió la {link:alliance}Alianza{/link} de {link:lordaeron}Lordaeron{/link} en la {link:second-war}Segunda Guerra{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Las historias dicen poco de la propia familia de Thoradin, de sus últimos años o de su muerte. Esta entrada no hace conjeturas sobre ellos.]=],
		},
	},
	chapters = {
		{
			title = "El Sigilo de Thoradin",
			hint = "Siga el sigilo roto que lleva el nombre del primer rey.",
			text = [=[Entre los sellos que guardan la tumba de los Trollbane hay un sigilo que lleva el nombre de Thoradin. El príncipe {link:prince-galen-trollbane}Galen{/link} lo rompió y repartió sus pedazos entre sus últimos defensores. Los pedazos fueron arrebatados de sus cuerpos, y un chamán trol de la {link:horde}Horda{/link} los volvió a unir. El nombre del primer rey se había convertido en una llave en manos de los trols que su pueblo derrotó un día.]=],
		},
	},
	mentions = {
		{ text = "El sigilo roto" },
		{ text = "Sigilo de Thoradin" },
	},
	bonds = {
		{ id = "arathor", name = "Arathor", note = "la nación que fundó" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "el último de su linaje" },
		{ id = "thoradin-s-wall", name = "Muralla de Thoradin", note = "lleva su nombre" },
		{ id = "stromgarde-keep", name = "Castillo de Stromgarde", note = "en otro tiempo su capital, Strom" },
	},
})

Translate("esMX", "thoras-trollbane", {
	title = "Thoras Trollbane",
	subtitle = "Difunto rey de Stromgarde",
	allegiance = "Reino de Stromgarde · Casa Trollbane",
	aliases = { "Thoras", "Rey Thoras" },
	sections = {
		{
			title = "Resumen",
			text = [=[Thoras Trollbane fue el rey de {link:stromgarde-keep}Stromgarde{/link}, heredero de la antigua casa que ha gobernado la ciudad desde que el linaje real de {link:arathor}Arathor{/link} la abandonó. Fue un rey guerrero en una tierra de soldados curtidos. Ahora está muerto, y su reino ha muerto con él. Yace en una tumba sellada en El Sagrario, tras la capilla de Stromgarde, con la espada de su casa a su lado.]=],
		},
		{
			title = "Importancia",
			text = [=[Thoras fue uno de los gobernantes que alzaron la {link:alliance}Alianza{/link} de {link:lordaeron}Lordaeron{/link} contra la {link:horde}Horda{/link}. Su casa desciende de Ignaeus, el general de las {link:troll-wars}Guerras Trols{/link} cuya hoja {link:trol-kalar}Trol'kalar{/link} dio su nombre a la familia. Para los trols de {link:azeroth}Azeroth{/link}, el nombre de Trollbane sigue siendo una maldición.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Llevó a {link:stromgarde-keep}Stromgarde{/link} a la {link:alliance}Alianza de Lordaeron{/link} en la {link:second-war}Segunda Guerra{/link}.
• Tras la guerra, cuando la Alianza discutió por los campos de internamiento y su coste, sacó a Stromgarde de ella.
• Fue sepultado con {link:trol-kalar}Trol'kalar{/link}, la espada de Ignaeus.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días registra cómo murió Thoras Trollbane. Su pueblo solo dice que se ha ido.]=],
		},
	},
	chapters = {
		{
			title = "La tumba de El Sagrario",
			hint = "Póngase ante la tumba del último rey de Stromgarde.",
			text = [=[La tumba del rey Thoras se encuentra tras la capilla del barrio de los defensores, vigilada por cuidadores de la casa. Su frente está tallada con líneas que ninguna mano puede abrir sin los sigilos que su hijo dispersó. En el puño de unas manos de piedra sobre la tumba yace {link:trol-kalar}Trol'kalar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Trollbane, la noticia de su muerte" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "Príncipe Galen Trollbane", note = "su hijo" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "su aliado en la Alianza" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "la espada de su casa" },
	},
})

Translate("esMX", "trol-kalar", {
	title = "Trol'kalar",
	sections = {
		{
			title = "Resumen",
			text = [=[Trol'kalar es la antigua espada de la casa Trollbane. Su nombre significa asesina de trols en la lengua de los propios trols. La empuñó en las guerras de {link:arathor}Arathor{/link} lord Ignaeus de {link:stromgarde-keep}Strom{/link}, el enemigo más temido al que los trols se enfrentaron jamás, y dio su nombre a su casa.]=],
		},
		{
			title = "La tumba",
			text = [=[Cuando murió el rey {link:thoras-trollbane}Thoras{/link}, Trol'kalar fue depositada en su tumba de El Sagrario, tras la capilla de {link:stromgarde-keep}Stromgarde{/link}, sujeta por unas manos de piedra. La tumba se selló con protecciones que solo responden a un sigilo. El príncipe {link:prince-galen-trollbane}Galen{/link} dividió ese sigilo en cuatro: el Sigilo de Strom, el Sigilo de {link:thoradin}Thoradin{/link}, el Sigilo de {link:arathor}Arathor{/link} y el Sigilo de Trollbane. Uno cayó en manos del {link:syndicate}Hermandad{/link} junto con la ciudad. Los otros los entregó a sus soldados, al jefe de su caballería y a sí mismo. Reunidos, los cuatro se convierten en uno, el Sigilo de Ignaeus.]=],
		},
		{
			title = "En la actualidad",
			text = [=[{link:vol-jin}Vol'jin{/link}, de los {link:darkspear-trolls}Lanza Negra{/link}, quiere la espada. Ha enviado al cazador {link:zengu}Zengu{/link} a {link:hammerfall}Sentencia{/link} para tomarla, de modo que la asesina de trols de {link:stromgarde-keep}Strom{/link} pueda volverse contra los trols Gurubashi de {link:zul-gurub}Zul'Gurub{/link}.]=],
		},
	},
})

Translate("esMX", "witherbark-trolls", {
	title = "Trols Secacorteza",
	aliases = { "Secacorteza", "trols Secacorteza", "tribu Secacorteza" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Secacorteza son una tribu de {link:trolls}trols{/link} del bosque que viven en el sureste de las {link:arathi-highlands}Tierras Altas de Arathi{/link}. Su poblado se alza allí entre las colinas, con cuevas detrás donde se reúnen los jefes de sus partidas de guerra. Los trols han luchado contra los humanos de {link:stromgarde-keep}Strom{/link} desde los días de {link:thoradin}Thoradin{/link}, y los Secacorteza aún llevan esa guerra muy dentro del corazón.]=],
		},
		{
			title = "Sus costumbres",
			text = [=[La tribu tiene lanzadores de hachas, cazadores de cabezas, rabiosos y médicos brujos que llevan bolsas de medicinas y amuletos de sanguinaria. Sus cazadores de las sombras reciben un cuchillo especial cuando completan sus ritos de paso. Dos jefes de partida de guerra, Zalas Witherbark y Nimar el Asesino, los llevan a la guerra.]=],
		},
		{
			title = "En la actualidad",
			text = [=[Los Secacorteza lucharon un día junto a los orcos, y después los abandonaron. Ahora se han unido a los {link:boulderfist-ogres}ogros Puño de Roca{/link} para expulsar a la {link:horde}Horda{/link} de {link:hammerfall}Sentencia{/link}. Sus combatientes comparten el túmulo de ogros de {link:boulder-gor}Roca'gor{/link}, y rabiosos de la tribu luchan junto a los ogros en las ruinas de {link:stromgarde-keep}Stromgarde{/link}. {link:drum-fel}Drum Fel{/link} de Sentencia los ha convertido en el primer objetivo de su guerra.]=],
		},
	},
})

Translate("esMX", "boulderfist-ogres", {
	title = "Ogros Puño de Roca",
	aliases = { "Puño de Roca", "ogros Puño de Roca", "clan Puño de Roca" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Puño de Roca son el mayor clan de {link:ogres}ogros{/link} de las {link:arathi-highlands}Tierras Altas de Arathi{/link}. Ocupan el túmulo de {link:boulder-gor}Roca'gor{/link}, las cuevas de la {link:boulderfist-hall}Sala Puño de Roca{/link} y gran parte de la ciudad en ruinas de {link:stromgarde-keep}Stromgarde{/link}. Ninguna crónica registra cuándo llegaron a las tierras altas.]=],
		},
		{
			title = "Sus costumbres",
			text = [=[Son brutos, ejecutores, machacadores y señores, con magos y chamanes que han aprendido a usar los tesoros que saquean. Sus chamanes aprecian las ágatas azures tomadas de la Torre de {link:arathor}Arathor{/link}. En la {link:boulderfist-hall}Sala Puño de Roca{/link}, el {link:ogres}ogro{/link} mago {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link} lanza hielo con una varita robada. En {link:stromgarde-keep}Stromgarde{/link}, el ogro {link:or-kalar}Or'Kalar{/link} los manda en nombre de {link:mug-thol}Mug'thol{/link}, un caudillo que no es de las tierras altas.]=],
		},
		{
			title = "En la actualidad",
			text = [=[Los Puño de Roca combaten a los soldados de {link:stromgarde-keep}Stromgarde{/link} y al {link:syndicate}Hermandad{/link} por las ruinas de la ciudad, y se han unido a los {link:witherbark-trolls}trols Secacorteza{/link} contra {link:hammerfall}Sentencia{/link}. Kovork, Molok el Triturador, {link:ruul-eagletalon}Ruul{/link} Onestone y Foulbelly son temidos entre sus jefes.]=],
		},
	},
})

Translate("esMX", "drywhisker-kobolds", {
	title = "Kóbolds Mostacho Seco",
	aliases = { "Mostacho Seco", "kóbolds Mostacho Seco" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Mostacho Seco son una tribu de {link:kobolds}kóbolds{/link} que excavan en el {link:drywhisker-gorge}Cañón Mostacho Seco{/link}, en el extremo noreste de las tierras altas. Son agrimensores y excavadores, y entre ellos trabaja un geomántico llamado Flintdagger que domina el fuego.]=],
		},
		{
			title = "Los fragmentos",
			text = [=[Los Mostacho Seco no son solo mineros. En lo profundo de su cañón guardan un grupo de fragmentos de cristal iridiscente, y llevan consigo motas de un poder extraño. El ser que yace atado bajo las tierras altas los llama aliados de los gigantes que la retienen. Tres de ellos caminan junto al mismísimo vigía de piedra {link:fozruk}Fozruk{/link}. Nadie sabe qué han dado los gigantes a los kóbolds por su servicio, ni si los kóbolds entienden siquiera a quién sirven.]=],
		},
	},
})

Translate("esMX", "league-of-arathor", {
	title = "Liga de Arathor",
	sections = {
		{
			title = "Resumen",
			text = [=[La Liga de Arathor es la fuerza de combate de lo que queda del reino de {link:stromgarde-keep}Stromgarde{/link}. Sus soldados son los herederos de un reino orgulloso cuya capital está ahora en manos de ogros y bandidos. Han jurado recuperar las tierras altas para el pueblo de Stromgarde y para la {link:alliance}Alianza{/link}.]=],
		},
		{
			title = "Su causa",
			text = [=[La Liga tiene su campamento en el {link:refuge-pointe}Refugio de la Zaga{/link}, bajo el mando del mariscal de campo {link:field-marshal-oslight}Oslight{/link}. Su primera batalla es por la {link:arathi-basin}Cuenca de Arathi{/link}, un valle fértil de granjas, minas, forjas y bosques. La Liga quiere reclamar las riquezas de la cuenca para sus aliados de {link:stormwind-city}Ventormenta{/link}, y a través de Ventormenta para toda la {link:alliance}Alianza{/link}. Sus soldados ocupan el Bastión de Aterratrols, en el borde del valle, que lleva el nombre de la casa real de {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "En la actualidad",
			text = [=[La Liga se enfrenta a los {link:defilers}Rapiñadores Renegados{/link} en la cuenca. Su oficial de intendencia, Samuel Hawke, envía provisiones a quienes luchan, y sus sargentos instan a cada soldado a golpear antes de que pueda hacerlo el enemigo.]=],
		},
	},
})

Translate("esMX", "defilers", {
	title = "Rapiñadores",
	aliases = { "Los Rapiñadores", "Rapiñadores Renegados" },
	sections = {
		{
			title = "Resumen",
			text = [=[Los Rapiñadores son tropas de élite de los {link:forsaken}Renegados{/link}, enviadas a las {link:arathi-highlands}Tierras Altas de Arathi{/link} bajo la atenta mirada de {link:varimathras}Varimathras{/link}. Luchan contra la {link:league-of-arathor}Liga de Arathor{/link} por la {link:arathi-basin}Cuenca de Arathi{/link}. Su propósito no es la guerra de los orcos sino la de su propia reina: separar a los humanos del norte de sus aliados enanos del sur, y apoderarse de las riquezas de la cuenca para {link:undercity}Entrañas{/link}.]=],
		},
		{
			title = "Su campamento",
			text = [=[Los Rapiñadores tienen su cuartel general en {link:hammerfall}Sentencia{/link}, junto a los orcos y trols del puesto avanzado, bajo el mando del maestro de la muerte {link:deathmaster-dwire}Dwire{/link}. En la cuenca ocupan la Guarida de los Rapiñadores. Su oficial de intendencia, Rutherford Twing, envía provisiones a quienes luchan por ellos, y el mortacechador Mortis sirve al lado de Dwire.]=],
		},
		{
			title = "En la actualidad",
			text = [=[{link:deathmaster-dwire}Dwire{/link} cree que incluso el pequeño campamento del {link:refuge-pointe}Refugio de la Zaga{/link} podría un día amenazar a la {link:horde}Horda{/link}. Los Rapiñadores quieren asegurarse de que {link:arathi-highlands}Arathi{/link} nunca vuelva a ser un hogar para los humanos.]=],
		},
	},
})
